using Microsoft.EntityFrameworkCore;using SchoolERP.Application.Exceptions;using SchoolERP.Domain.Entities;using SchoolERP.Domain.Enums;using Xunit;namespace SchoolERP.IntegrationTests;
[Collection(PostgresCollection.Name)]public sealed class SchoolCalendarPersistenceTests(PostgresFixture database){[PostgresFact]public async Task Tenant_filter_and_school_code_uniqueness_are_enforced(){var a=Tenant.Create("Calendar A","cal-a-"+Guid.NewGuid().ToString("N"));var b=Tenant.Create("Calendar B","cal-b-"+Guid.NewGuid().ToString("N"));var sa=School.Create(a,"School A","A");var sb=School.Create(b,"School B","B");var ea=Create(a.Id,sa.Id,"A");var eb=Create(b.Id,sb.Id,"B");await using(var setup=database.CreateContext(platformAccess:true)){setup.Schools.AddRange(sa,sb);setup.SchoolCalendarEvents.AddRange(ea,eb);await setup.SaveChangesAsync();}await using(var scoped=database.CreateContext(a.Id)){Assert.Equal(ea.Id,(await scoped.SchoolCalendarEvents.SingleAsync()).Id);}await using(var duplicate=database.CreateContext(a.Id)){duplicate.SchoolCalendarEvents.Add(Create(a.Id,sa.Id,"Duplicate"));await Assert.ThrowsAsync<SchoolCalendarCodeConflictException>(()=>duplicate.SaveChangesAsync());}}private static SchoolCalendarEvent Create(Guid tenant,Guid school,string title)=>SchoolCalendarEvent.Create(tenant,school,null,null,title,"EVENT",SchoolCalendarEventType.SchoolEvent,new(2026,10,12),new(2026,10,12),true,null,null,false,null,null,null);}
